"""B2 upper-intermediate lessons 46–60 for Learn Language Academy by Parth."""
_RAW = [[46,"Plus-Que-Parfait - The Past Before the Past","Explain an earlier past event and sequence past events clearly.",["déjà|already|day-zhah|/de.ʒa|J'avais déjà mangé.","auparavant|previously|oh-pah-rah-vahn|/o.pa.ʁa.vɑ̃|Je l'avais vu auparavant.","la veille|the day before|lah vay|/la vɛj|Elle était partie la veille.","se rendre compte|to realise|suh rahndr kohn-tuh|/sə ʁɑ̃dʁ kɔ̃t|Je m'étais rendu compte de l'erreur.","oublier|to forget|oo-blee-yay|/u.bli.je|Il avait oublié son sac.","prévenir|to warn|pray-vuh-neer|/pʁe.və.niʁ|Nous l'avions prévenu.","un retard|a delay|uhn ruh-tahr|/œ̃ ʁə.taʁ|Le train avait du retard.","une expérience|an experience|ün ehk-spay-ree-ahns|/yn ɛk.spe.ʁjɑ̃s|J'avais vécu une expérience utile.","se produire|to happen|suh proh-dweer|/sə pʁɔ.dɥiʁ|Que s'était-il produit ?","jusque-là|until then|zhüsk-lah|/ʒysk.la|Tout avait bien fonctionné jusque-là.","un témoignage|a testimony|uhn tay-mwah-nyazh|/œ̃ te.mwa.ɲaʒ|Elle avait laissé un témoignage.","réaliser|to realise|ray-ah-lee-zay|/ʁe.a.li.ze|J'avais réalisé mon erreur."]],[47,"Advanced Future and Conditional Structures","Use future and conditional forms in complex time clauses, hypotheses and polite exchanges.",["dès que|as soon as|deh kuh|/dɛ kə|Dès que j'aurai fini, je partirai.","tant que|as long as|tahn kuh|/tɑ̃ kə|Tant que tu travailleras, tu progresseras.","à condition que|provided that|ah kohn-dee-syohn kuh|/a kɔ̃.di.sjɔ̃ kə|À condition que tu sois prêt.","au cas où|in case|oh kah oo|/o ka u|Au cas où il pleuvrait…","une échéance|a deadline|ün ay-shay-ahns|/yn e.ʃe.ɑ̃s|L'échéance approche.","un engagement|a commitment|uhn ahn-gazh-mahn|/œ̃n ɑ̃.ɡaʒ.mɑ̃|Je tiendrai mon engagement.","éventuellement|possibly|ay-vahn-tü-ehl-mahn|/e.vɑ̃.ty.ɛl.mɑ̃|Nous pourrions éventuellement reporter.","prévoir|to anticipate|pray-vwahr|/pʁe.vwaʁ|Il faudra prévoir une solution.","supposer|to suppose|sü-poh-zay|/sy.po.ze|Supposons que cela fonctionne.","une conséquence|a consequence|ün kohn-say-kahns|/yn kɔ̃.se.kɑ̃s|Cela aurait une conséquence.","probable|likely|proh-bahbl|/pʁɔ.babl|C'est peu probable.","un scénario|a scenario|uhn say-nah-ryoh|/œ̃ se.na.ʁjo|Envisageons un autre scénario."]],[48,"Subjunctive Present - Expressing Necessity and Emotion","Recognise and form the present subjunctive after necessity, emotion, doubt and judgement.",["il faut que|it is necessary that|eel foh kuh|/il fo kə|Il faut que tu viennes.","bien que|although|byan kuh|/bjɛ̃ kə|Bien qu'il soit tard…","pour que|so that|poor kuh|/puʁ kə|Je répète pour que tu comprennes.","à moins que|unless|ah mwan kuh|/a mwɛ̃ kə|À moins qu'elle refuse…","je doute que|I doubt that|zhuh doot kuh|/ʒə dut kə|Je doute qu'il sache.","être content que|to be glad that|ehtr kohn-tahn kuh|/ɛtʁ kɔ̃.tɑ̃ kə|Je suis content que tu sois là.","craindre que|to fear that|krehn-druh kuh|/kʁɛ̃dʁ kə|Je crains qu'il ne soit trop tard.","une exigence|a requirement|ün ehk-zee-zhahns|/yn ɛɡ.zi.ʒɑ̃s|C'est une exigence importante.","quoique|although|kwah-kuh|/kwa.kə|Quoiqu'il fasse froid…","il est possible que|it is possible that|eel eh poh-see-bl kuh|/il ɛ pɔ.sibl kə|Il est possible qu'elle vienne.","une volonté|willingness|ün voh-lohn-tay|/yn vɔ.lɔ̃.te|C'est sa volonté.","suffire|to be sufficient|sü-feer|/sy.fiʁ|Il suffit que tu participes."]],[49,"Si Clauses and Conditional Sentences","Build realistic and hypothetical conditional sentences and distinguish the main French si patterns.",["si jamais|if ever|see zhah-meh|/si ʒa.mɛ|Si jamais tu as besoin…","à moins de|unless|ah mwan duh|/a mwɛ̃ də|À moins de changer d'avis…","une condition|a condition|ün kohn-dee-syohn|/yn kɔ̃.di.sjɔ̃|C'est une condition essentielle.","une hypothèse|a hypothesis|ün ee-poh-tez|/yn i.pɔ.tɛz|Formulons une hypothèse.","réussir|to succeed|ray-ü-seer|/ʁe.y.siʁ|Si nous essayons, nous réussirons.","échouer|to fail|ay-shoo-ay|/e.ʃwe|Sans aide, il échouerait.","imaginer|to imagine|ee-mah-zhee-nay|/i.ma.ʒi.ne|Imagine si tu pouvais choisir.","un risque|a risk|uhn reesk|/œ̃ ʁisk|Il y aurait un risque.","une éventualité|a possibility|ün ay-vahn-tü-ah-lee-tay|/yn e.vɑ̃.ty.a.li.te|Il faut envisager cette éventualité.","se passer|to happen|suh pah-say|/sə pa.se|Que se passerait-il ?","dans le cas où|in the event that|dahn luh kah oo|/dɑ̃ lə ka u|Dans le cas où tu serais absent…","sinon|otherwise|see-nohn|/si.nɔ̃|Dépêche-toi, sinon tu seras en retard."]],[50,"Passive Voice and Impersonal Structures","Use passive voice and impersonal constructions to focus on actions, processes and general statements.",["être réalisé|to be carried out|ehtr ray-ah-lee-zay|/ɛtʁ ʁe.a.li.ze|Le projet est réalisé ici.","être interdit|to be prohibited|ehtr an-tehr-dee|/ɛtʁ ɛ̃.tɛʁ.di|Il est interdit de fumer.","être autorisé|to be authorised|ehtr oh-toh-ree-zay|/ɛtʁ o.tɔ.ʁi.ze|L'accès est autorisé.","une mesure|a measure|ün muh-zür|/yn mə.zyʁ|Une mesure a été annoncée.","un règlement|a regulation|uhn reh-gluh-mahn|/œ̃ ʁɛ.ɡlə.mɑ̃|Le règlement est appliqué.","être chargé de|to be responsible for|ehtr shar-zhay duh|/ɛtʁ ʃaʁ.ʒe də|Le service est chargé de l'accueil.","il est nécessaire|it is necessary|eel eh nay-say-sehr|/il ɛ ne.se.sɛʁ|Il est nécessaire de vérifier.","il semble que|it seems that|eel sahmbl kuh|/il sɑ̃bl kə|Il semble que la situation change.","on|one; people; we|ohn|/ɔ̃|On parle français ici.","une procédure|a procedure|ün proh-say-dür|/yn pʁɔ.se.dyʁ|La procédure est expliquée.","être considéré comme|to be considered as|ehtr kohn-see-day-ray kohm|/ɛtʁ kɔ̃.si.de.ʁe kɔm|Cette règle est considérée comme utile.","un responsable|a person in charge|uhn reh-spohn-sahbl|/œ̃ ʁɛs.pɔ̃.sabl|Le responsable sera contacté."]],[51,"Reported Speech and Indirect Questions","Report what people say, ask and think while adjusting tense, pronouns and question word order.",["rapporter|to report|rah-pohr-tay|/ʁa.pɔʁ.te|Elle rapporte les faits.","déclarer|to declare|day-klah-ray|/de.kla.ʁe|Il a déclaré qu'il viendrait.","affirmer|to assert|ah-feer-may|/a.fiʁ.me|Elle affirme avoir raison.","demander si|to ask whether|duh-mahn-day see|/də.mɑ̃.de si|Il demande si tu viens.","une déclaration|a statement|ün day-klah-rah-syohn|/yn de.kla.ʁa.sjɔ̃|Sa déclaration est claire.","un renseignement|information|uhn rahn-sayn-yuh-mahn|/œ̃ ʁɑ̃.sɛ.ɲə.mɑ̃|Je voudrais un renseignement.","se demander|to wonder|suh duh-mahn-day|/sə də.mɑ̃.de|Je me demande où il est.","prétendre|to claim|pray-tahn-druh|/pʁe.tɑ̃dʁ|Il prétend qu'il sait.","une rumeur|a rumour|ün rü-muhr|/yn ʁy.muʁ|La rumeur circule.","confirmer|to confirm|kohn-feer-may|/kɔ̃.fiʁ.me|Elle confirme qu'elle viendra.","un discours|a speech|uhn dees-koor|/œ̃ dis.kuʁ|Il a prononcé un discours.","selon|according to|suh-lohn|/sə.lɔ̃|Selon elle, tout va bien."]],[52,"Advanced Pronouns and Pronoun Order","Combine object pronouns accurately in affirmative, negative, compound and imperative structures.",["le lui|it to him/her|luh lwee|/lə lɥi|Je le lui donne.","la leur|it to them|lah luhr|/la lœʁ|Elle la leur apporte.","m'en|some to me|mahn|/mɑ̃|Tu m'en donnes ?","s'y|to it; there|see|/si|Il s'y intéresse.","s'en|of it; away from it|sahn|/sɑ̃|Elle s'en souvient.","un ordre|an order|uhn ohr-druh|/œ̃n ɔʁdʁ|L'ordre des pronoms est fixe.","remettre|to hand over|ruh-mehtr|/ʁə.mɛtʁ|Je le lui remets.","se souvenir de|to remember|suh soo-vuh-neer duh|/sə su.və.niʁ də|Je m'en souviens.","s'intéresser à|to be interested in|sahn-tay-ray-say ah|/sɛ̃.te.ʁe.se a|Elle s'y intéresse.","en parler|to talk about it|ahn par-lay|/ɑ̃ paʁ.le|Nous allons en parler.","y penser|to think about it|ee pahn-say|/i pɑ̃.se|Je vais y penser.","une combinaison|a combination|ün kohn-bee-neh-zohn|/yn kɔ̃.bi.ne.zɔ̃|Cette combinaison est correcte."]],[53,"Complex Sentence Construction","Build longer, coherent sentences using subordinate clauses, infinitive structures, connectors and punctuation.",["une subordonnée|a subordinate clause|ün sü-bohr-doh-nay|/yn sy.bɔʁ.dɔ.ne|La subordonnée complète l'idée.","bien que|although|byan kuh|/bjɛ̃ kə|Bien qu'il soit occupé…","tandis que|whereas|tahn-dee kuh|/tɑ̃.di kə|Je travaille tandis qu'il étudie.","afin de|in order to|ah-fan duh|/a.fɛ̃ də|Afin de réussir, pratique.","à force de|by dint of|ah fohrs duh|/a fɔʁs də|À force de répéter, tu progresses.","une conséquence|a consequence|ün kohn-say-kahns|/yn kɔ̃.se.kɑ̃s|La conséquence est importante.","un enchaînement|a sequence|uhn ahn-shen-mahn|/œ̃n ɑ̃.ʃɛn.mɑ̃|L'enchaînement est logique.","quoique|although|kwah-kuh|/kwa.kə|Quoiqu'elle soit fatiguée…","pourvu que|provided that|poor-vü kuh|/puʁ.vy kə|Pourvu que tout se passe bien.","un raisonnement|reasoning|uhn reh-zohn-mahn|/œ̃ ʁɛ.zɔn.mɑ̃|Son raisonnement est clair.","en revanche|on the other hand|ahn ruh-vahnsh|/ɑ̃ ʁə.vɑ̃ʃ|En revanche, le coût augmente.","notamment|notably|noht-mahn|/nɔ.ta.mɑ̃|Notamment dans ce contexte."]],[54,"Conjunctions and Linking Expressions","Choose precise connectors for cause, consequence, contrast, concession, purpose and sequence.",["par conséquent|consequently|par kohn-say-kahn|/paʁ kɔ̃.se.kɑ̃|Par conséquent, nous attendrons.","néanmoins|nevertheless|nay-ahhn-mwahn|/ne.ɑ̃.mwɛ̃|Néanmoins, il faut agir.","en effet|indeed|ahn nay-feh|/ɑ̃n e.fɛ|En effet, le coût a augmenté.","étant donné que|given that|ay-tahn doh-nay kuh|/e.tɑ̃ dɔ.ne kə|Étant donné qu'il pleut…","bien que|although|byan kuh|/bjɛ̃ kə|Bien que ce soit difficile…","de sorte que|so that|duh sohrt kuh|/də sɔʁt kə|Il explique de sorte que chacun comprenne.","toutefois|however|toot-fwah|/tut.fwa|Toutefois, une réserve demeure.","en outre|furthermore|ahn ootruh|/ɑ̃ utʁ|En outre, le délai est court.","alors que|whereas|ah-lohr kuh|/a.lɔʁ kə|Alors que le prix baisse…","faute de|for lack of|foht duh|/fot də|Faute de temps, nous partirons.","grâce à|thanks to|grahs ah|/ɡʁas a|Grâce à votre aide…","par ailleurs|moreover|par ah-yuhr|/paʁ a.jœʁ|Par ailleurs, une autre option existe."]],[55,"Banking, Finance and Administrative Vocabulary","Handle banking, payment, budgeting and administrative interactions with precise vocabulary.",["un compte courant|a current account|uhn kohn-tuh koo-rahn|/œ̃ kɔ̃t ku.ʁɑ̃|J'ouvre un compte courant.","un virement|a bank transfer|uhn veer-mahn|/œ̃ viʁ.mɑ̃|J'effectue un virement.","un relevé|a statement|uhn ruhl-vay|/œ̃ ʁə.lə.ve|Je consulte mon relevé.","des frais|fees|day freh|/de fʁɛ|Y a-t-il des frais ?","un taux d'intérêt|an interest rate|uhn toh dan-tay-reh|/œ̃ to dɛ̃.te.ʁɛ|Le taux d'intérêt change.","un prélèvement|a direct debit|uhn pray-lehv-mahn|/œ̃ pʁe.lɛv.mɑ̃|Le prélèvement est automatique.","une échéance|a due date|ün ay-shay-ahns|/yn e.ʃe.ɑ̃s|L'échéance est le 15.","un justificatif|supporting document|uhn zhüs-tee-fee-kah-teef|/œ̃ ʒys.ti.fi.ka.tif|Il faut un justificatif.","un formulaire|a form|uhn fohr-mü-lehr|/œ̃ fɔʁ.my.lɛʁ|Remplissez le formulaire.","un budget|a budget|uhn büzhay|/œ̃ by.dʒɛ|Je respecte mon budget.","une facture|a bill|ün fahk-tür|/yn fak.tyʁ|La facture est payée.","un remboursement|a refund|uhn rahn-boors-mahn|/œ̃ ʁɑ̃.buʁs.mɑ̃|Je demande un remboursement."]],[56,"Technology, Internet and Digital Communication","Discuss devices, online services, privacy, troubleshooting and digital communication.",["un appareil|a device|uhn ah-pah-ray|/œ̃n a.pa.ʁɛj|Mon appareil ne fonctionne plus.","un logiciel|software|uhn loh-zhee-syehl|/œ̃ lɔ.ʒi.sjɛl|Le logiciel est à jour.","une mise à jour|an update|ün mees ah zhoor|/yn miz a ʒuʁ|La mise à jour est disponible.","un mot de passe|a password|uhn moh duh pahs|/œ̃ mo də pas|Change ton mot de passe.","une pièce jointe|an attachment|ün pyehs zhwanht|/yn pjɛs ʒwɛ̃t|J'ajoute une pièce jointe.","télécharger|to download|tay-lay-shar-zhay|/te.le.ʃaʁ.ʒe|Télécharge le document.","téléverser|to upload|tay-lay-vehr-say|/te.le.vɛʁ.se|Téléverse le fichier.","un réseau|a network|uhn ray-zoh|/œ̃ ʁe.zo|Le réseau est lent.","la confidentialité|privacy|lah kohn-fee-dahn-syah-lee-tay|/la kɔ̃.fi.dɑ̃.sja.li.te|La confidentialité est essentielle.","une panne|an outage|ün pahn|/yn pan|Il y a une panne.","sécuriser|to secure|say-kü-ree-zay|/se.ky.ʁi.ze|Il faut sécuriser le compte.","un lien|a link|uhn lyan|/œ̃ ljɛ̃|Clique sur le lien."]],[57,"News, Media and Current Affairs","Understand news reports, distinguish fact from opinion and discuss current events cautiously.",["un reportage|a news report|uhn ruh-pohr-tazh|/œ̃ ʁə.pɔʁ.taʒ|J'ai regardé un reportage.","un titre|a headline|uhn tee-truh|/œ̃ titʁ|Le titre est accrocheur.","une source|a source|ün soors|/yn suʁs|Vérifie la source.","une enquête|an investigation|ün ahn-keht|/yn ɑ̃.kɛt|L'enquête se poursuit.","un témoin|a witness|uhn tay-mwan|/œ̃ te.mwɛ̃|Un témoin a parlé.","un enjeu|an issue|uhn ahn-zhuh|/œ̃n ɑ̃.ʒø|L'enjeu est important.","un sondage|a poll|uhn sohn-dazh|/œ̃ sɔ̃.daʒ|Le sondage révèle une tendance.","selon les médias|according to the media|suh-lohn lay may-dyah|/sə.lɔ̃ le me.dja|Selon les médias, le débat continue.","une couverture|coverage|ün koo-vehr-tür|/yn ku.vɛʁ.tyʁ|La couverture médiatique est large.","vérifier|to verify|vay-ree-fee-ay|/ve.ʁi.fi.e|Il faut vérifier les faits.","une rumeur|a rumour|ün rü-muhr|/yn ʁy.muʁ|Ne partage pas une rumeur.","un éditorial|an editorial|uhn ay-dee-toh-ryahl|/œ̃n e.di.tɔ.ʁjal|L'éditorial exprime une opinion."]],[58,"Debates, Arguments and Persuasion","Present a position, support it with evidence, respond to objections and persuade respectfully.",["un point de vue|a viewpoint|uhn pwan duh vü|/œ̃ pwɛ̃ də vy|Je comprends ton point de vue.","soutenir|to support|soo-tuh-neer|/su.tə.niʁ|Je soutiens cette proposition.","un argument|an argument|uhn ar-gü-mahn|/œ̃n aʁ.ɡy.mɑ̃|Cet argument est solide.","une objection|an objection|ün ohb-zhehk-syohn|/yn ɔb.ʒɛk.sjɔ̃|Je comprends cette objection.","nuancer|to qualify|nü-ahn-say|/nɥɑ̃.se|Il faut nuancer le propos.","convaincre|to convince|kohn-vahnkruh|/kɔ̃.vɛ̃kʁ|Elle cherche à convaincre.","une preuve|evidence|ün pruhv|/yn pʁœv|Quelle preuve avez-vous ?","en revanche|on the other hand|ahn ruh-vahnsh|/ɑ̃ ʁə.vɑ̃ʃ|En revanche, le coût baisse.","certes|admittedly|sehrt|/sɛʁt|Certes, le plan est ambitieux.","toutefois|however|toot-fwah|/tut.fwa|Toutefois, il reste un risque.","une concession|a concession|ün kohn-say-syohn|/yn kɔ̃.se.sjɔ̃|Faisons une concession.","à long terme|in the long term|ah lohn tehrm|/a lɔ̃ tɛʁm|À long terme, ce choix est utile."]],[59,"Canadian French Idioms and Informal Speech","Recognise Canadian French idioms, understand their register and choose when to use them.",["c'est le fun|it's fun|seh luh feuhn|/sɛ lə fœn|C'était le fun !","magasiner|to shop|mah-gah-zee-nay|/ma.ɡa.zi.ne|On va magasiner samedi.","un dépanneur|a convenience store|uhn day-pah-nuhr|/œ̃ de.pa.nœʁ|Je passe au dépanneur.","une tuque|a knitted hat|ün tü-k|/yn tyk|Mets ta tuque, il fait froid.","char|car (informal Quebec)|shahr|/ʃaʁ|Mon char est au garage.","pantoute|not at all (informal)|pahn-toot|/pɑ̃.tut|Pas pantoute !","c'est correct|that's fine|seh koh-rehk|/sɛ kɔ.ʁɛkt|Oui, c'est correct.","être tanné de|to be fed up with|ehtr tah-nay duh|/ɛtʁ ta.ne də|Je suis tanné d'attendre.","une fin de semaine|a weekend|ün fan duh suh-men|/yn fɛ̃ də sə.mɛn|Bonne fin de semaine !","un chum|boyfriend; male friend (context)|uhn shuhm|/œ̃ tʃœm|Je sors avec mon chum.","une blonde|girlfriend (context)|ün blohnd|/yn blɔ̃d|Sa blonde arrive bientôt.","ça marche|that works|sah marsh|/sa maʁʃ|D'accord, ça marche."]],[60,"B2 Comprehensive Revision and Assessment","Integrate B2 grammar, discourse, argumentation and practical communication.",["une synthèse|a synthesis|ün san-tehz|/yn sɛ̃.tɛz|Rédige une synthèse.","une nuance|a nuance|ün nü-ahns|/yn nɥɑ̃s|La nuance est importante.","un enchaînement|a sequence|uhn ahn-shen-mahn|/œ̃n ɑ̃.ʃɛn.mɑ̃|L'enchaînement est cohérent.","une hypothèse|a hypothesis|ün ee-poh-tez|/yn i.pɔ.tɛz|Il formule une hypothèse.","un témoignage|a testimony|uhn tay-mwah-nyazh|/œ̃ te.mwa.ɲaʒ|Le témoignage est crédible.","une objection|an objection|ün ohb-zhehk-syohn|/yn ɔb.ʒɛk.sjɔ̃|Réponds à l'objection.","une conséquence|a consequence|ün kohn-say-kahns|/yn kɔ̃.se.kɑ̃s|La conséquence est claire.","un registre|a register|uhn ruh-zheestr|/œ̃ ʁə.ʒistʁ|Adapte le registre.","une tournure|a phrasing|ün toor-nür|/yn tuʁ.nyʁ|Cette tournure est naturelle.","un point de vue|a viewpoint|uhn pwan duh vü|/œ̃ pwɛ̃ də vy|Défends ton point de vue.","approfondir|to deepen|ah-proh-fohn-deer|/a.pʁɔ.fɔ̃.diʁ|Il faut approfondir le sujet.","maîtriser|to master|meh-tree-zay|/mɛ.tʁi.ze|Elle maîtrise les structures."]]]
_GRAMMAR = [["Form the plus-que-parfait with the imparfait of avoir or être plus a past participle: j'avais terminé; elle était partie. The auxiliary is conjugated in the imparfait, not the present.","Use the same auxiliary choice as in the passé composé: most verbs take avoir; selected movement/change-of-state verbs and all pronominal verbs take être.","With être, agree the participle with the subject. With avoir, agreement generally occurs when a direct object precedes the verb: les lettres que j'avais écrites.","Use plus-que-parfait for an event earlier than another past reference point: Quand je suis arrivé, le film avait commencé.","Negation surrounds the auxiliary: je n'avais pas compris. Questions keep the auxiliary before the participle: Avais-tu déjà visité la ville ?","Déjà, auparavant, jusque-là and la veille can clarify that an event happened before another past moment.","Do not use plus-que-parfait for every past event. Use it when the earlier-than-another-past relationship matters.","The tense is standard across French-speaking Canada. Pay attention to auxiliary choice and written agreement, which may not be audible."],["The future simple uses the infinitive (remove final e for -re verbs) plus -ai, -as, -a, -ons, -ez, -ont. Irregular stems include ser-, aur-, ir-, fer-, viendr- and voudr-.","Form futur antérieur with avoir or être in the future plus a past participle: j'aurai terminé; elle sera partie.","After quand, lorsque, dès que and aussitôt que, French often uses a future tense for a future event: Dès que tu arriveras, nous commencerons.","Use the future stem plus imparfait endings for conditional present: je pourrais, nous aimerions.","Form conditionnel passé with avoir or être in the conditional plus a past participle: j'aurais accepté; elle serait venue.","A past unrealised condition commonly uses plus-que-parfait and conditionnel passé. Match each clause to its actual time.","Au cas où is commonly followed by the conditional: Prends un parapluie au cas où il pleuvrait.","Future and conditional forms are used in Canadian French; the near future is frequent in conversation."],["For many verbs, take the ils/elles present form, remove -ent and add -e, -es, -e, -ions, -iez, -ent. Nous and vous often use the nous-form stem.","Know irregular être (sois, sois, soit, soyons, soyez, soient), avoir (aie, aies, ait, ayons, ayez, aient), aller (aille), faire (fasse), pouvoir (puisse), savoir (sache) and vouloir (veuille).","Il faut que, il est nécessaire que and il est essentiel que commonly introduce the subjunctive: Il faut que nous partions.","Je suis heureux que, je regrette que and il est dommage que express emotion or judgement and commonly take the subjunctive.","Je doute que and il est possible que normally take the subjunctive. Je pense que and je crois que generally take the indicative in affirmative statements.","Bien que, pour que, afin que, avant que and à moins que are followed by the subjunctive in standard usage.","The subjunctive reflects how a clause is framed; it is not simply a future tense. Necessity, emotion and doubt are common triggers.","The same subjunctive grammar applies in Canadian French. Full forms are expected in careful writing."],["For a realistic condition, use si + present followed by present, future or imperative: Si tu viens, nous partirons.","For an unreal or imagined present/future, use si + imparfait followed by conditional present: Si j'avais le choix, je resterais.","For an unreal past, use si + plus-que-parfait followed by conditionnel passé: Si j'avais su, je serais venu.","Do not put the conditional directly after si in these standard patterns. Avoid *si j'aurais* and *si j'aurais su*.","A past condition can have a present consequence: Si j'avais accepté ce poste, je vivrais à Montréal.","À condition que and pourvu que take the subjunctive; à condition de and faute de can be followed by an infinitive or noun.","Au cas où and dans le cas où commonly take the conditional: au cas où tu aurais besoin d'aide.","Conditional patterns are shared across French varieties. The common spoken error si j'aurais is non-standard."],["Use être + past participle: Le rapport est publié. The past participle agrees with the grammatical subject.","The active object becomes the passive subject: Le comité a adopté la mesure → La mesure a été adoptée par le comité.","Conjugate être in the required tense: est annoncé, était annoncé, a été annoncé, sera annoncé. Keep agreement.","Par introduces the agent in many action passives. De appears with certain states and established expressions.","Use passive when the action or result matters more than the actor, especially in reports and instructions.","Il faut, il est possible, il semble and il vaut mieux allow general statements without naming a person.","On can mean people, one or we and often sounds more natural than a passive in conversation.","Passive and impersonal structures occur in Canadian administrative and professional language. Prefer clear phrasing."],["Use dire que, expliquer que, annoncer que, prétendre que and demander si to report information. Adjust pronouns and time references to context.","A reported statement with que keeps normal clause order: Elle dit qu'elle est prête.","With a past reporting verb, present may shift to imparfait, passé composé to plus-que-parfait and future to conditional, depending on time relationships.","Yes/no indirect questions use si: Il demande si tu viens. Information questions keep the question word: Elle demande où tu habites.","Report a command with demander/ordonner/conseiller de + infinitive: Il m'a demandé de patienter.","Change je, tu, ici and demain only when the reporting viewpoint requires it. Changes are contextual, not mechanical.","Some reporting verbs take an infinitive: Elle affirme connaître la réponse.","Indirect speech is useful in news and workplace updates. Keep indirect questions in statement word order."],["Before a conjugated verb, the usual sequence is me/te/se/nous/vous, then le/la/les, then lui/leur, then y, then en: Je le lui donne.","With compound tenses, the pronoun group comes before the auxiliary: Je le lui ai expliqué; elle en a acheté.","With infinitives, place pronouns immediately before the infinitive they belong to: Je vais le lui expliquer.","Put ne before the pronoun group and pas after the conjugated verb: Je ne le lui donne pas.","In affirmative commands, attach pronouns after the verb with hyphens: Donne-le-moi; allez-y; parlez-lui-en.","In negative commands, pronouns return before the verb: Ne me le donne pas; n'y allez pas.","Se combines with y or en in forms such as s'y habituer and s'en souvenir. Learn each verb's preposition.","Pronoun sequences are shared across varieties. Practise them as complete chunks."],["A complex sentence combines a main clause with dependent clauses. Each clause needs a clear grammatical relationship and usually its own subject and verb.","Use parce que, puisque and étant donné que for causes; donc, ainsi, par conséquent and si bien que for results.","Bien que + subjunctive, même si + indicative and malgré + noun express concession in different forms.","Use pour + infinitive when the subject is the same; use pour que + subjunctive when the subject changes.","Après avoir terminé, avant de partir and sans prévenir allow concise sequencing.","Combine ideas with qui, que, dont, où and indirect questions. Keep the antecedent and pronoun role clear.","Place introductory clauses carefully and use commas to make long sentences readable. Avoid stacking redundant connectors.","In speech, break complex ideas into clear units and use connectors to guide the listener."],["Parce que gives a direct reason; puisque presents a reason treated as known; étant donné que is more formal. Grâce à is positive; à cause de is often negative.","Donc and alors are common consequences; par conséquent and en conséquence are more formal. Si bien que introduces a result clause.","Mais is neutral; cependant, toutefois and néanmoins are more formal. En revanche contrasts two sides.","Bien que and quoique take subjunctive; même si takes indicative. Malgré is followed by a noun or pronoun.","Pour + infinitive usually shares the subject; afin que and pour que take subjunctive when introducing a different subject.","De plus, en outre and par ailleurs add information. D'ailleurs often introduces a related point.","À condition que takes subjunctive; à condition de takes infinitive. Faute de means for lack of; sinon means otherwise.","Choose connectors that suit the audience. Avoid repeating the same connector in every sentence."],["Use ouvrir un compte, effectuer un virement, déposer de l'argent and retirer de l'argent. Ask about fees and processing times before confirming.","Un relevé de compte lists transactions; le solde is the balance. Distinguish available balance from pending transactions.","Des frais bancaires are fees; un taux d'intérêt is an interest rate. Read conditions and ask whether the rate is fixed or variable.","Payer une facture, effectuer un prélèvement automatique and demander un remboursement are common actions.","Un justificatif supports a request; une pièce d'identité proves identity; un formulaire must be completed accurately.","Use Pourriez-vous m'expliquer…? Quels frais s'appliquent ? and Je souhaiterais contester cette opération.","Financial terms and processes vary by institution and jurisdiction. Confirm local requirements.","In formal interactions, use vous and keep figures, dates and account details precise."],["Distinguish appareil, ordinateur, logiciel, application and système. Use fonctionner, redémarrer, installer and mettre à jour for troubleshooting.","Télécharger commonly means download; téléverser is used for upload in Canadian French, while interface terminology varies.","Use un compte, un identifiant, un mot de passe and une authentification à deux facteurs. Never share credentials.","Describe problems precisely: Mon appareil ne répond plus; la connexion est interrompue; le fichier est corrompu.","Joindre un fichier, envoyer un lien, répondre à tous and mettre en copie are useful email actions.","Les données personnelles, le consentement and la collecte de données are key privacy terms.","Use veuillez + infinitive or an imperative for clear steps. Sequence with d'abord, ensuite, puis and enfin.","Quebec interfaces often use téléverser for upload and courriel for email. Recognise local and international forms."],["Identify headline, date, outlet, author and source. Separate the reported event from the journalist's interpretation.","A fact can be checked against evidence; an opinion expresses judgement. Attribution signals the source of a claim.","Un reportage, une enquête, un éditorial, un communiqué and un sondage refer to different media content.","Check the original source, publication date, corroboration and whether a headline accurately represents the article.","Use sembler, selon, probablement and il serait possible que to reflect uncertainty. Do not present allegations as established facts.","Un sondage révèle une tendance; les chiffres indiquent une hausse; interpret results cautiously.","State the main event, evidence and differing positions without adding unsupported judgement.","Canadian media vocabulary overlaps with international French; explain unfamiliar local references."],["Introduce the issue, state a clear position, provide reasons, support them with evidence and finish with a conclusion.","Use examples, data and credible sources. Distinguish evidence from personal experience and avoid overgeneralising from one example.","Certes… cependant… acknowledges a point before responding. Je reconnais que…, toutefois… is useful for respectful disagreement.","Use dans une certaine mesure, généralement and sous certaines conditions to avoid overstatement.","Use il serait préférable de, il est essentiel de and cela permettrait de for measured recommendations.","Restate an objection fairly, identify its assumption and answer with reasons or evidence.","Ask Pourriez-vous préciser…? and Si je comprends bien… to clarify. Respond to the argument rather than the person.","In academic and professional settings, clarity, evidence and respectful qualification are effective."],["Some expressions are strongly associated with Quebec or Canadian French. Learn their meaning and register rather than assuming they are universal.","Char can mean car in informal Quebec speech; chum and blonde can refer to a partner depending on context.","Dépanneur means convenience store in Quebec; tuque is a knitted hat; magasiner means to shop.","C'est le fun and pantoute are informal. They may fit casual conversation but not every workplace or academic setting.","Informal speech may shorten words and reduce sounds. Understand the full standard form first.","Ça marche and c'est correct can mean that works or that's fine. Tone and context matter.","Vocabulary differs among Quebec, Acadian, Franco-Ontarian and other French-speaking communities.","This lesson is descriptive, not a list of forms required everywhere. Keep standard alternatives available."],["Distinguish completed past, background past, earlier-than-past, future completion and hypothetical results.","Review necessity, emotion, doubt and conjunctions that trigger the subjunctive; contrast with factual assertions.","Review si + present, si + imparfait and si + plus-que-parfait patterns. Never place conditional directly after si in these standard patterns.","Use passive voice when the action matters and indirect speech to report statements and questions with appropriate word order.","Check object pronoun order, y and en, and placement with infinitives, compound tenses and imperatives.","Use connectors for cause, consequence, concession, contrast and purpose. Keep long sentences logical and readable.","Apply precise vocabulary to finance, technology, media and argumentation; adjust register to audience.","Recognise regional vocabulary while maintaining standard grammar and a clear distinction between formal and informal usage."]]
def _build(item):
    lesson_id,title,goal,raw_vocab=item
    vocabulary=[tuple(x.split("|")) for x in raw_vocab]
    expressions=[
      ("Il convient de…","It is appropriate to…","Formal recommendation."),
      ("Cela dit…","That said…","Introduces a qualification."),
      ("Dans la mesure où…","To the extent that…","Introduces a condition or explanation."),
      ("Il va de soi que…","It goes without saying that…","Expresses an assumption."),
      ("Quoi qu'il en soit…","In any case…","Returns to the main point."),
      ("Je tiens à préciser que…","I would like to clarify that…","Clarifies an important detail."),
      ("À cet égard…","In this regard…","Connects a point to the topic."),
      ("Il n'en demeure pas moins que…","The fact remains that…","Maintains a point despite a concession."),
      ("Pour autant…","Even so…","Introduces a limit or contrast."),
      ("Sous réserve de…","Subject to…","Formal qualification or condition.")
    ]
    examples=[
      (vocabulary[0][4],vocabulary[0][1].capitalize()+".","Target vocabulary in a complete sentence."),
      ("Il convient que nous examinions toutes les possibilités avant de prendre une décision.","It is appropriate that we examine every possibility before making a decision.","An impersonal expression introduces a subjunctive clause."),
      ("Si nous avions reçu l'information plus tôt, nous aurions pu agir autrement.","If we had received the information earlier, we could have acted differently.","Si + plus-que-parfait is followed by conditionnel passé."),
      ("Le rapport, qui avait été révisé la veille, sera publié dès que la direction l'aura approuvé.","The report, which had been revised the day before, will be published as soon as management has approved it.","Relative clause, passive voice and future anterior."),
      ("Bien que cette solution soit coûteuse, elle pourrait réduire les risques à long terme.","Although this solution is expensive, it could reduce long-term risks.","Bien que takes the subjunctive."),
      ("Je me demande si l'équipe leur en a déjà parlé.","I wonder whether the team has already spoken to them about it.","Indirect question and combined pronouns.")
    ]
    conversations=[
      ("Clarifying a project decision",[("A","Le rapport indique que la procédure avait déjà été modifiée."),("B","Pourtant, personne ne nous en avait informés."),("A","Il faudrait vérifier qui avait autorisé le changement."),("B","D'accord. Je demanderai que les documents nous soient transmis.")],"A: The report indicates that the procedure had already been changed. B: Yet no one had informed us. A: We should check who authorised the change. B: All right. I'll ask for the documents to be sent to us."),
      ("A respectful debate",[("A","Je comprends cet argument, mais je ne suis pas entièrement convaincu."),("B","Pourriez-vous préciser ce qui vous préoccupe ?"),("A","Je crains que les coûts ne soient sous-estimés."),("B","C'est possible. Il faudrait donc examiner d'autres données.")],"A: I understand that argument, but I'm not entirely convinced. B: Could you clarify what concerns you? A: I'm afraid the costs are being underestimated. B: That's possible. We should examine other data."),
      ("A Canadian French conversation",[("A","On va magasiner après le travail ?"),("B","Ça marche, mais je dois passer au dépanneur avant."),("A","Pas de problème. On se retrouve à quelle heure ?"),("B","Vers six heures, si ça te convient.")],"A: Shall we go shopping after work? B: That works, but I have to stop at the convenience store first. A: No problem. What time shall we meet? B: Around six, if that suits you.")
    ]
    questions=[]
    for i,v in enumerate(vocabulary):
      opts=[v[1],vocabulary[(i+1)%len(vocabulary)][1],vocabulary[(i+2)%len(vocabulary)][1],vocabulary[(i+3)%len(vocabulary)][1]]
      questions.append((f"What does « {v[0]} » mean?",opts,0,f"« {v[0]} » means {v[1]}."))
    questions.extend([
      ("Which tense expresses an event completed before another past event?",["Plus-que-parfait","Imparfait","Future simple","Present"],0,"Plus-que-parfait places an event before another past reference point."),
      ("Which form follows « bien que » in standard French?",["Subjunctive","Future only","Infinitive only","Conditional"],0,"Bien que is followed by the subjunctive."),
      ("Which is the standard hypothetical past pattern?",["Si + plus-que-parfait, conditionnel passé","Si + conditionnel, future","Si + future, present","Si + subjunctive, imperative"],0,"An unreal past condition uses plus-que-parfait and conditionnel passé."),
      ("Which is a correct indirect yes/no question?",["Il demande si tu viens.","Il demande viens-tu.","Il demande est-ce que tu viens ?","Il demande que viens-tu."],0,"Indirect yes/no questions use si and statement word order."),
      ("Which pronoun sequence is standard?",["Je le lui donne.","Je lui le donne.","Je le donne lui.","Je lui donne le."],0,"The direct object pronoun le precedes the indirect lui."),
      ("Which connector signals concession?",["Bien que","Par conséquent","Grâce à","Afin de"],0,"Bien que introduces concession and takes subjunctive."),
      ("In Quebec French, « un dépanneur » commonly means…",["a convenience store","a mechanic","a pharmacy only","a bus stop"],0,"Un dépanneur is a convenience store in Quebec usage."),
      ("Which phrase qualifies a statement formally?",["Dans une certaine mesure","Pantoute","Ça roule","À tantôt"],0,"Dans une certaine mesure means to a certain extent.")
    ])
    assessment=(questions*2)[:20]
    speaking=[
      "Read all twelve vocabulary entries aloud, focusing on liaison, nasal vowels and the French R.",
      "Explain the central grammar pattern in your own words and create three original examples.",
      "Transform three direct statements into reported speech or another target structure.",
      "Give a two-minute explanation of a complex issue, using at least five linking expressions.",
      "Practise the dialogues twice: slowly for accuracy, then at a natural conversational pace.",
      "Summarise a news item or professional situation, distinguishing facts, interpretations and uncertainty.",
      "State an opinion, acknowledge an opposing argument and respond with evidence or a reasoned qualification.",
      "For regional vocabulary, explain the register and give a standard alternative where one exists."
    ]
    summary=[
      f"Use the vocabulary of « {title} » accurately in context.",
      "Apply the grammar structures with correct tense, agreement, pronoun position and clause order.",
      "Choose connectors and expressions according to meaning, register and audience.",
      "Practise dialogues and speaking tasks without translating word for word.",
      "Mistakes never block lesson completion or the next chapter."
    ]
    topic_examples=[(f"Dans le cadre de « {title} », le terme « {vocabulary[0][0]} » doit être interprété avec précision.",f"In the context of {title}, the term « {vocabulary[0][0]} » must be interpreted precisely.","This lesson-specific example applies the chapter vocabulary in a precise sentence.")]
    examples=topic_examples+examples
    topic_conversation=(f"Clarifying {title.lower()}",[("A",f"Comment interprétez-vous « {vocabulary[0][0]} » ?"),("B","Il faut tenir compte du contexte, du sens et du registre."),("A","La situation change-t-elle l'interprétation ?"),("B","Oui, le contexte permet de préciser le sens.")],f"A: How do you interpret « {vocabulary[0][0]} »? B: We must take context, meaning and register into account. A: Does the situation change the interpretation? B: Yes, context helps clarify the meaning.")
    conversations=[topic_conversation]+conversations
    return {"title":title,"goal":goal,"vocab":vocabulary,"vocabulary":vocabulary,"grammar":list(zip(["Core pattern","Form and structure","Meaning and use","Accuracy and common pitfalls","Questions and negative forms","Advanced usage","Choosing the right construction","Canadian French focus"],_GRAMMAR[lesson_id-46])),"expressions":expressions,"examples":examples,"conversations":conversations,"exercises":questions,"speaking":speaking,"summary":summary,"assessment":assessment}
B2_LESSONS={item[0]:_build(item) for item in _RAW}
